changeSet.sql:
DROP TABLE IF EXISTS concept_field_config CASCADE;
DO $$
BEGIN
    IF to_regclass('field_form_config_concept') IS NOT NULL THEN
        ALTER TABLE field_form_config_concept
        ADD COLUMN IF NOT EXISTS fk_vocabulary_id bigint,
        ADD COLUMN IF NOT EXISTS field_code varchar(255);
    END IF;
    IF to_regclass('field_form_config_concept_aud') IS NOT NULL THEN
        ALTER TABLE field_form_config_concept_aud
        ADD COLUMN IF NOT EXISTS fk_vocabulary_id bigint,
        ADD COLUMN IF NOT EXISTS fk_vocabulary_id_mod boolean,
        ADD COLUMN IF NOT EXISTS field_code varchar(255),
        ADD COLUMN IF NOT EXISTS field_code_mod boolean;
    END IF;
END
$$;
